import {C as store} from './index-BLVOhKhN.js?v=20261007-loading9';
import {weekOf,completedStages} from './star-map-state-20261004.js?v=20261007-loading9';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function refresh(){const main=document.querySelector('main');if(!main)return;const state=store.getState().starMapChallenge||{},week=weekOf(Date.now()),progress=state.weeks?.[week]?.progress||0;
 let home=document.getElementById('star-map-home');if(location.pathname==='/'){const journey=main.querySelector('[data-home-journey]');if(journey){if(!home){home=document.createElement('section');home.id='star-map-home';home.className='sm-home';home.setAttribute('aria-label','This week’s themed challenge');journey.after(home)}const sig=week+':'+progress;if(home.dataset.signature!==sig){home.dataset.signature=sig;home.innerHTML=`<img src="/art/challenges/star-map.svg" alt="Observatory star map"><div><p class="sm-kicker">THIS WEEK’S EXPEDITION</p><h2>Repair the star map</h2><p>${progress>=8?'This week’s map collected':`${completedStages(progress)}/4 sections restored`}</p><a href="/play/weekly-boss/">${progress>=8?'View completed expedition':'Continue the expedition'} →</a></div>`}}}else home?.remove();
 let gallery=document.getElementById('star-map-collection');if(location.pathname.replace(/\/$/,'')!=='/garden'){gallery?.remove();return}if(!gallery){gallery=document.createElement('section');gallery.id='star-map-collection';gallery.className='sm-collection';gallery.setAttribute('aria-label','Star map collection');main.append(gallery)}const items=Object.values(state.collection||{}).filter(x=>x.theme==='star-map').sort((a,b)=>b.week.localeCompare(a.week)),sig=JSON.stringify(items);if(gallery.dataset.signature===sig)return;gallery.dataset.signature=sig;gallery.innerHTML=`<p class="sm-kicker">EXPEDITION COLLECTION</p><h2>Observatory Star Maps</h2>${items.length?`<div class="sm-collection-grid">${items.map(x=>`<article class="sm-collection-item"><img class="sm-badge" src="/art/challenges/star-map.svg" alt="Restored Observatory Star Map"><strong>${esc(x.name)}</strong><p>Weekly edition · ${esc(x.week)}</p><span>Collected</span></article>`).join('')}</div>`:'<p>Restore all four sections of this week’s star map to earn your first edition.</p>'}<a href="/play/weekly-boss/">Open this week’s expedition →</a>`;if(location.hash==='#star-map-collection')gallery.scrollIntoView({block:'start'});
}
if(!document.querySelector('[data-star-map-style]')){const css=document.createElement('link');css.rel='stylesheet';css.href='/assets/star-map-challenge-20261004.css?v=1';css.dataset.starMapStyle='';document.head.append(css)}
let queued=false;function schedule(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh()})}new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});store.subscribe(schedule);window.addEventListener('popstate',schedule);window.addEventListener('storage',schedule);window.addEventListener('hashchange',schedule);schedule();
